<?php require_once __DIR__.'/includes/bootstrap.php';require_role('farmer');$u=current_user();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$cat=(int)($_POST['category_id']??0);$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$unit=trim($_POST['unit']??'kg');$loc=trim($_POST['location']??'');$photo=trim($_POST['photo']??'');$desc=trim($_POST['description']??'');if(!$name||$cat<1||$price===false||$price<=0||$qty===false||$qty<0||!$loc||!in_array($unit,['kg','bunch','piece','crate','bag','litre'],true)||($photo&&!filter_var($photo,FILTER_VALIDATE_URL))){flash('error','Check all fields. Price must be positive; quantity cannot be negative; photo must be a valid URL.');}else{if($id){$st=$pdo->prepare("UPDATE produce SET name=?,category_id=?,price=?,quantity=?,unit=?,location=?,photo=?,description=?,status='pending' WHERE id=? AND farmer_id=?");$st->execute([$name,$cat,$price,$qty,$unit,$loc,$photo?:null,$desc,$id,$u['id']]);flash('success','Listing updated and sent for approval.');}else{$st=$pdo->prepare("INSERT INTO produce(farmer_id,category_id,name,price,quantity,unit,location,photo,description,status) VALUES(?,?,?,?,?,?,?,?,?,'pending')");$st->execute([$u['id'],$cat,$name,$price,$qty,$unit,$loc,$photo?:null,$desc]);flash('success','Listing created and sent for approval.');}redirect('farmer.php');}}elseif($action==='delete'){$st=$pdo->prepare('DELETE FROM produce WHERE id=? AND farmer_id=?');$st->execute([(int)$_POST['id'],$u['id']]);flash('success','Listing removed.');redirect('farmer.php');}}$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM produce WHERE id=? AND farmer_id=?');$st->execute([(int)$_GET['edit'],$u['id']]);$edit=$st->fetch();}$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$st=$pdo->prepare('SELECT p.*,c.name category_name FROM produce p JOIN categories c ON c.id=p.category_id WHERE p.farmer_id=? ORDER BY p.created_at DESC');$st->execute([$u['id']]);$items=$st->fetchAll();include __DIR__.'/includes/header.php'; ?>
<section class="page-banner"><span class="eyebrow">FARMER WORKSPACE</span><h1>Manage your produce</h1><p>New and edited listings require administrator approval before buyers can see them.</p></section><section class="section"><div class="two-col"><form class="panel form-panel" method="post"><h2><?= $edit?'Edit listing':'Add a listing' ?></h2><?= csrf_field() ?><?= show_flash() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Produce name</label><input name="name" required maxlength="120" value="<?= e($edit['name']??'') ?>"><label>Category</label><select name="category_id" required><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>" <?= (int)($edit['category_id']??0)===$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><div class="form-grid"><div><label>Price (KSh)</label><input type="number" name="price" min="0.01" step="0.01" required value="<?= e($edit['price']??'') ?>"></div><div><label>Quantity</label><input type="number" name="quantity" min="0" required value="<?= e($edit['quantity']??'') ?>"></div></div><label>Unit</label><select name="unit"><?php foreach(['kg','bunch','piece','crate','bag','litre'] as $unit): ?><option <?= ($edit['unit']??'kg')===$unit?'selected':'' ?>><?= $unit ?></option><?php endforeach; ?></select><label>Location</label><input name="location" required maxlength="150" value="<?= e($edit['location']??'') ?>"><label>Photo URL (optional)</label><input type="url" name="photo" value="<?= e($edit['photo']??'') ?>" placeholder="https://example.com/photo.jpg"><label>Description</label><textarea name="description" rows="3" maxlength="1000"><?= e($edit['description']??'') ?></textarea><button class="btn">Save listing</button></form><div><h2>Your listings</h2><div class="listing-stack"><?php foreach($items as $p): ?><article class="panel listing"><div><h3><?= e($p['name']) ?></h3><p><?= e($p['category_name']) ?> · KSh <?= number_format($p['price'],2) ?> / <?= e($p['unit']) ?></p><span class="status"><?= e(ucfirst($p['status'])) ?></span></div><div class="listing-actions"><a href="farmer.php?edit=<?= $p['id'] ?>">Edit</a><form method="post" onsubmit="return confirm('Remove this listing?')"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="link-button danger">Remove</button></form></div></article><?php endforeach; ?><?php if(!$items): ?><p class="muted">You have not added any listings yet.</p><?php endif; ?></div></div></div></section><?php include __DIR__.'/includes/footer.php'; ?>